function validate([root]) {
  if (!Array.isArray(root) || root.length !== 3 || root.some(v => v === null)) return 'The tree has exactly 3 nodes: a root and its two children.';
  if (root.some(v => !Number.isInteger(v) || v < -100 || v > 100)) return 'Each node value is an integer from -100 to 100.';
  return null;
}

