function checkTree(root) {
  // Visit the tree in preorder, collecting values: root first, then left, then right.
  const values = [];
  const visit = node => {
    if (!node) return;
    values.push(node.val);
    visit(node.left);
    visit(node.right);
  };
  visit(root);
  return values[0] - values[1] - values[2] === 0;
}

