function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const span = size === 'large' ? 100 : 10;
  const left = pick(-span, span);
  const right = pick(-span, span);
  let value = pick(-span, span);
  // Make about half of the trees satisfy the rule, when the sum stays in range.
  if (rand() < 0.5 && Math.abs(left + right) <= 100) value = left + right;
  return [[value, left, right]];
}
